def encode(message):
    """
    Write a function that takes a message, and encodes in such a way that it swaps case of all letters, replaces all vowels in the message with the letter that appears 2 places ahead of that vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    vowels = 'aeiouAEIOUAEIOU'
    result = []
    for char in message:
        if char.isalpha():
            if char.lower() in vowels:
                # Replace vowel
                vowel_index = vowels.index(char.lower())
                new_vowel = vowels[(vowel_index + 2) % 5]
                result.append(new_vowel)
            else:
                # Swap case
                if char.isupper():
                    result.append(char.lower())
                else:
                    result.append(char.upper())
        else:
            # Ignore non-letters
            pass
    return ''.join(result)

