def prod_signs(arr):
    if not arr:
        return None
    product_of_signs = 1
    sum_of_abs = 0
    for num in arr:
        if num == 0:
            sum_of_abs += 0
        else:
            product_of_signs *= -1 if num < 0 else 1
            sum_of_abs += abs(num)
    return product_of_signs * sum_of_abs

def tri(n):
    """Everyone knows Fibonacci sequence, it was studied deeply by mathematicians in 
    the last couple centuries. However, what people don't know is Tribonacci sequence.
    Tribonacci sequence is defined by the recurrence:
    tri(1) = 3
    tri(n) = 1 + n / 2, if n is even.
    tri(n) = tri(n - 1) + tri(n - 2) + tri(n + 1), if n is odd.
    For example:
    tri(3) = [1, 3, 2, 8]
    """
    # Initialize the list with the first two terms
    tri_list = [3, 1]
    if n == 0:
        return tri_list[:n]
    elif n == 1:
        return tri_list[:n]
    else:
        for i in range(2, n):
            if i % 2 == 0:
                tri_list.append(1 + i // 2)
            else:
                tri_list.append(tri_list[-1] + tri_list[-2] + tri_list[-3])
        return tri_list[:n]

